import { ReactNode } from 'react';
import { Annotation } from '../../core/components/annotations-timeseries/types/annotations.js';
/** The annotations marker slot props */
export interface AnnotationsMarkerProps {
    /** Annotation data point. */
    data: Annotation;
    /** Annotation markers color (hex, rgba, token). */
    color?: string;
    /** Priority of annotation. */
    priority?: number;
    /** Annotation marker character (letter/emoji/icon/glyph or Unicode character). */
    symbol?: ReactNode;
    /** Flag to hide a marker */
    hidden?: boolean;
}
